code_sketch:
struct Glyph: Hashable { let code: String; let w: Int; let h: Int }  // intrinsic

enum GlyphFactory {                                // FlyweightFactory
    private static var pool: [Glyph: Glyph] = [:]
    static func of(_ code: String, _ w: Int, _ h: Int) -> Glyph {
        let key = Glyph(code: code, w: w, h: h)
        if let hit = pool[key] { return hit }
        pool[key] = key
        return key
    }
}
struct Cell { let glyph: Glyph; let x: Int; let y: Int }   // extrinsic state
